        </tr>)}</tbody>
      </table>}
    </section> : <section>
      <h2>Ramp overview</h2>
      {/* TODO: show each ramp with its matching visible loadings and an empty message. */}
      <ul>{ramps.map(ramp => <li key={ramp.id}>{ramp.name} ({ramp.id}) — assignments to implement</li>)}</ul>
